const input = Array.isArray($json) ? $json : [$json];
const weights = { 'personal-injury': 5, 'mass-tort': 5, family: 3, immigration: 3, criminal: 4, estate: 2, employment: 3, other: 1 };
const rows = input.map((call) => {
  const text = `${call.voicemailText ?? ''}`.toLowerCase();
  const caseTypeHint = `${call.caseTypeHint ?? 'other'}`.toLowerCase();
  const practiceWeight = weights[caseTypeHint] ?? 1;
  const urgencySignals = ['accident today', 'just happened', 'arrested', 'served papers', 'injunction', 'imminent', 'emergency'];
  const urgencyHits = urgencySignals.filter((term) => text.includes(term)).length;
  const repeatBonus = call.repeatCaller ? 1 : 0;
  const priorityScore = practiceWeight + urgencyHits + repeatBonus;
  return { ...call, priorityScore, queue: priorityScore >= 6 ? 'call-now' : priorityScore >= 4 ? 'call-within-4h' : 'next-business-day' };
});
return rows.sort((a, b) => b.priorityScore - a.priorityScore).map((row) => ({ json: row }));
